package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;

@RunWith(JUnit4.class)
public class CommandLine_hasOption_TriageGen2Test {

    @Test
    public void testHasOption_String() {
        CommandLine commandLine = new CommandLine();
        commandLine.addOption(new Option("opt1"));
        assertTrue(commandLine.hasOption("opt1"));

        assertFalse(commandLine.hasOption("opt2"));
    }

    @Test
    public void testHasOption_String_Null() {
        CommandLine commandLine = new CommandLine();
        assertNull(commandLine.getOptions());
        assertFalse(commandLine.hasOption("opt1"));
    }

    @Test
    public void testHasOption_String_EmptyList() {
        CommandLine commandLine = new CommandLine();
        Option[] options = new Option[0];
        commandLine.setOptions(options);
        assertFalse(commandLine.hasOption("opt1"));
    }

    @Test
    public void testHasOption_String_NullOption() {
        CommandLine commandLine = new CommandLine();
        Option option = null;
        commandLine.addOption(option);
        assertFalse(commandLine.hasOption("opt1"));
    }

    @Test
    public void testHasOption_Char() {
        CommandLine commandLine = new CommandLine();
        commandLine.addOption(new Option('a'));
        assertTrue(commandLine.hasOption('a'));

        assertFalse(commandLine.hasOption('b'));
    }

    @Test
    public void testHasOption_Char_Null() {
        CommandLine commandLine = new CommandLine();
        assertNull(commandLine.getOptions());
        assertFalse(commandLine.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_EmptyList() {
        CommandLine commandLine = new CommandLine();
        Option[] options = new Option[0];
        commandLine.setOptions(options);
        assertFalse(commandLine.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_NullOption() {
        CommandLine commandLine = new CommandLine();
        Option option = null;
        commandLine.addOption(option);
        assertFalse(commandLine.hasOption('a'));
    }
}
